static void logline(int group, int idx, const char *text)
{
    if (g_nlines < 64) {
        Line *l = &g_lines[g_nlines];
        l->tick = (unsigned)xTaskGetTickCount();
        l->group = group;
        l->idx = idx;
        l->seq = g_nlines;
        snprintf(l->text, sizeof l->text, "%s", text);
        g_nlines++;
    }
}

static void error_line(int idx, const char *what)
{
