    snprintf(buf, sizeof buf, "ERROR: %s %s", g_name[idx], what);
    logline(1, idx, buf);
}

static int bad_idx(int idx)
{
    if (idx < 0 || idx >= g_n) {
        printf("ERROR: module index %d out of range\n", idx);
        return 1;
    }
    if (g_st[idx] != 0) {
        error_line(idx, "handled twice");
        return 1;
